import assert from 'node:assert/strict';
import source from './legacy-2018-spring-pm13-source-review.json';
import {readSpringPm13Expression as read,evaluateSpringPm13Expression as evaluate,resolveSpringPm13Write as write,type Environment,type Scalar} from './legacy-2018-spring-pm13-expression';
export type SpringPm13Banks=Record<'a'|'b'|'c'|'d'|'e'|'f',string[]>;
const decode=(s:string)=>s.replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&quot;','"').replaceAll('&#x27;',"'").replaceAll('&#39;',"'");
export const springPm13Plain=(s:string)=>decode(s.replace(/<[^>]*>/g,''));
function restoreHoles(s:string){return s.replace(/<span\b[^>]*data-source-token="([^"]*)"[^>]*>[\s\S]*?<\/span>/g,(_,token:string)=>decode(token));}
export function readSpringPm13Bank(html:string,bank:keyof SpringPm13Banks){assert(html.includes(`data-spring-pm13-bank="${bank}"`));const caption=html.indexOf('<figcaption>'),table=html.indexOf('data-spring-pm13-bank=');assert(caption>=0&&caption<table);const opts=[...html.matchAll(/<div class="spring2018-pm13-bank-row"[^>]*data-spring-pm13-option="(\d+)"><span>([^<]*)<\/span><code>([\s\S]*?)<\/code><\/div>/g)];assert.equal(opts.length,source.banks[bank].length);return opts.map((m,i)=>{assert.equal(+m[1],i);assert.equal(m[2],'アイウエオカキク'[i]);return springPm13Plain(m[3]);});}
/** Every actual rendered line and structural end is fixed against the original
 * source ledger before an independent macro interpreter is allowed to run. */
export function readSpringPm13Macro(html:string){assert.equal((html.match(/<u data-spring-pm13-number-type="true">数値型<\/u>/g)??[]).length,1,"QS72 numeric type underline");const rows=[...html.matchAll(/<div\b[^>]*data-spring-pm13-line="(\d+)"[^>]*data-spring-pm13-line-kind="([^"]*)"[^>]*>([\s\S]*?)<\/div>/g)];assert.equal(rows.length,source.macroLines.length);const actual=rows.map((m,i)=>{assert.equal(+m[1],i);assert.equal(m[2],source.macroLines[i].kind);let text=springPm13Plain(restoreHoles(m[3]));if(source.macroLines[i].kind==='statement'){assert(text.startsWith('・'));text=text.slice(1);}if([5,8,11,14].includes(i)){assert.equal(text,i===5||i===8?'■':'▼');text='';}assert.equal(text,source.macroLines[i].text);return{kind:m[2],text};});assert.deepEqual([...html.matchAll(/data-spring-pm13-control="([^"]+)"/g)].map(m=>m[1]),['for','if-date','post-test','if-overlap']);return actual;}
export function readSpringPm13Formula(html:string,kind:'copy'|'recommend'){const m=html.match(/<div class="spring2018-pm13-formula">([\s\S]*?)<\/div>/);assert(m);const text=springPm13Plain(restoreHoles(m[1])).replaceAll('／','/').replaceAll('’',"'");assert.equal(text,kind==='copy'?"IF(論理和(［a］),0,D$19/B2)":"IF(［b］,'なし',［c］)");return text;}
function numeric(value:ReturnType<typeof evaluate>){assert.equal(typeof value,'number');return value as number;}
const names=['a','b','c','d','e','f']as const;
export function inspectSpringPm13AllChoices(banks:SpringPm13Banks,frames:{copy:string;recommend:string},macroHtml:string){readSpringPm13Macro(macroHtml);for(const bank of names)assert.deepEqual(banks[bank],source.banks[bank]);const ok=Object.fromEntries(names.map(k=>[k,banks[k].map(()=>true)])) as Record<keyof SpringPm13Banks,boolean[]>;const witnesses=Object.fromEntries(names.map(k=>[k,banks[k].map(()=>null)])) as Record<keyof SpringPm13Banks,(unknown|null)[]>;let checks=0;
 const trial=(bank:keyof SpringPm13Banks,index:number,description:unknown,actual:()=>boolean)=>{checks++;try{if(!actual()){ok[bank][index]=false;witnesses[bank][index]??=description;}}catch(error){ok[bank][index]=false;witnesses[bank][index]??={description,error:(error as Error).message};}};
 const aExpr=banks.a.map(s=>read(frames.copy.replace('［a］',s)));
 for(let row=2;row<=16;row++)for(const capacity of[1,2,5,20])for(const people of[0,1,2,3,20])for(const requires of[false,true])for(const has of[false,true])for(const available of[false,true]){const env:Environment={copyRows:row-2,get:(_,r,c)=>r===19?(c===4?people:c===5?(requires?'要':'不要'):null):r===row?(c===2?capacity:c===3?(has?'有':'無'):c===4?(available?'可':'否'):null):null},expected=people>capacity||requires&&!has||!available?0:people/capacity;aExpr.forEach((e,j)=>trial('a',j,{row,capacity,people,requires,has,available},()=>numeric(evaluate(e,env))===expected));}
 const patterns:number[][]=[[...Array(15).fill(0)],[...Array(15).fill(1)],[...Array(15).fill(.5)]];for(let code=0;code<81;code++){let n=code;const first=Array.from({length:4},()=>{const x=[0,.5,1][n%3];n=Math.floor(n/3);return x;});for(const shift of[0,4,10]){const r=Array(15).fill(0);first.forEach((v,j)=>r[(shift+j)%15]=v);patterns.push(r);}}
 const bExpr=banks.b.map(read),cExpr=banks.c.map(read);for(const rates of patterns){const ids=Array.from({length:15},(_,i)=>501+7*i),env:Environment={get:(_,r,c)=>r>=2&&r<=16?c===5?rates[r-2]:c===1?ids[r-2]:null:null},expectedNone=rates.every(r=>r===0);bExpr.forEach((e,j)=>trial('b',j,{rates},()=>evaluate(e,env)===expectedNone));if(!expectedNone){const highest=Math.max(...rates),expected=ids[rates.findIndex(r=>r===highest)];cExpr.forEach((e,j)=>trial('c',j,{rates},()=>evaluate(e,env)===expected));}}
 const dExpr=banks.d.map(read),times=[900,1000,1100,1200,1300,1400,1500];for(const start of times)for(const end of times)if(start<end)for(const wantedStart of times)for(const wantedEnd of times)if(wantedStart<wantedEnd){const env:Environment={variables:{J:1},get:(sheet,r,c)=>sheet==='予約リスト'&&r===2?(c===3?start:c===4?end:null):r===19?(c===2?wantedStart:c===3?wantedEnd:null):null},nonOverlap=Math.max(start,wantedStart)>=Math.min(end,wantedEnd);dExpr.forEach((e,j)=>trial('d',j,{start,end,wantedStart,wantedEnd},()=>evaluate(e,env)===nonOverlap));}
 const eExpr=banks.e.map(read);for(const ids of[Array.from({length:15},(_,i)=>100+i),Array.from({length:15},(_,i)=>114-i),Array.from({length:15},(_,i)=>100+(i*7)%15)])for(let position=1;position<=30;position++){const booked=Array.from({length:32},(_,j)=>ids[(j*7+3)%15]),env:Environment={variables:{J:position},get:(sheet,r,c)=>sheet==='予約リスト'?(c===7?booked[r-2]??null:null):(c===1&&r>=2&&r<=16?ids[r-2]:c===4?'可':null)},expected=ids.indexOf(booked[position-1])+2;eExpr.forEach((e,j)=>trial('e',j,{ids,position,booked},()=>{const target=write(e,env);return target.sheet===''&&target.column===4&&target.row===expected;}));}
 const fExpr=banks.f.map(read),date=20180415;for(const days of[[date],[date,date,date],[date-1,date,date,date+1],[date-1,date],[date-1,date-1,date,date]])for(let j=0;j<fExpr.length;j++){trial('f',j,{days},()=>{const scanned:number[]=[],env:Environment={variables:{J:days.indexOf(date)+1},get:(sheet,r,c)=>sheet==='予約リスト'?(c===2?days[r-2]??null:c===3?1000:c===4?1200:null):r===19?(c===1?date:c===2?900:c===3?1300:null):null};let pos=days.indexOf(date)+1;do{assert(scanned.length<=days.length+1,'loop fails to end');scanned.push(pos);env.variables!.J=++pos;}while(evaluate(fExpr[j],env));const expected=days.flatMap((day,i)=>day===date?[i+1]:[]);return JSON.stringify(scanned)===JSON.stringify(expected);});}
 for(const bank of names){const wanted={a:1,b:4,c:3,d:4,e:2,f:0}[bank];assert.deepEqual(ok[bank].flatMap((v,i)=>v?[i]:[]),[wanted],bank+' unique correct');ok[bank].forEach((v,i)=>{if(!v)assert(witnesses[bank][i],bank+'/'+i+' counterexample');});}
 return{checks,truth:ok,witnesses};}
export function independentSpringPm13Macro(banks:SpringPm13Banks,macroHtml:string,rooms:{id:number}[],records:{date:number;start:number;end:number;room:number}[],request:{date:number;start:number;end:number}){readSpringPm13Macro(macroHtml);const available=Array(15).fill(true),d=read(banks.d[4]),e=read(banks.e[2]),f=read(banks.f[0]);assert.equal(rooms.length,15);const first=records.findIndex(r=>r.date===request.date);if(first<0)return available;let J=first+1,iterations=0;const env:Environment={variables:{J},get:(sheet,row,column)=>{if(sheet==='予約リスト'){const r=records[row-2];return!r?null:column===2?r.date:column===3?r.start:column===4?r.end:column===7?r.room:null;}if(row===19)return column===1?request.date:column===2?request.start:column===3?request.end:null;if(column===1&&row>=2&&row<=16)return rooms[row-2].id;if(column===4&&row>=2&&row<=16)return available[row-2]?'可':'否';return null;}};do{assert(++iterations<=records.length+1);env.variables!.J=J;if(evaluate(d,env)===false){const cell=write(e,env);assert(cell.sheet===''&&cell.column===4&&cell.row>=2&&cell.row<=16);available[cell.row-2]=false;}env.variables!.J=++J;}while(evaluate(f,env));return available;}
